export type CanvasThemeManifest = {
  id: string;
  name: string;
  tier: "included" | "premium";
  nodeVariant: "card" | "shield";
  cssScope: string;
  voice: {
    // Data-only: manifests cross the RSC boundary and must stay serializable
    // (and future marketplace themes ship as JSON packages).
    generationLabels: Record<string, string>;
    unknownAncestor: string;
    livingPrivacy: string;
    /** "{firstName}" is replaced with the focus person's given name. */
    storyLinkTemplate: string;
    scrollCue: string;
  };
};
--- REGISTRY ---
import { midnightArchiveTheme } from "@/lib/themes/midnight-archive";
import type { CanvasThemeManifest } from "@/lib/themes/types";

const defaultTheme = midnightArchiveTheme;
const themes = new Map<string, CanvasThemeManifest>([[defaultTheme.id, defaultTheme]]);

export function getCanvasTheme(themeId?: string | null) {
  return (themeId && themes.get(themeId)) || defaultTheme;
}

export { defaultTheme as defaultCanvasTheme };
