import { ThemedTreeCanvas } from "@/components/canvas-themed/themed-tree-canvas";
import { getShowcaseGenerations } from "@/lib/showcase/pilot-showcase";
import { getSyntheticPilotProject } from "@/lib/showcase/project";
import { getCanvasTheme } from "@/lib/themes/registry";

type PageQuery = Record<string, string | string[] | undefined>;

export default async function PilotPreviewTreePage({
  params,
  searchParams,
}: {
  params: Promise<{ projectId: string }>;
  searchParams: Promise<PageQuery>;
}) {
  const { projectId } = await params;
  const query = await searchParams;
  const project = await getSyntheticPilotProject(projectId);
  const personId = stringParam(query.person) ?? project.focalPersonId ?? "p03";
  const requestedDepth = Number.parseInt(stringParam(query.depth) ?? "1", 10);
  const depth = Number.isFinite(requestedDepth)
    ? Math.min(3, Math.max(1, requestedDepth))
    : 1;
  const lineageId = stringParam(query.lineage);
  const canvas = getShowcaseGenerations(project, personId, depth, lineageId);
  const basePath = `/projects/${project.id}/preview`;
  const configuredTheme = (project as typeof project & { canvasTheme?: string }).canvasTheme;
  const theme = getCanvasTheme(configuredTheme);

  return (
    <ThemedTreeCanvas
      layout={canvas.layout}
      focusPerson={canvas.focusPerson}
      theme={theme}
      familyName={project.welcome.familyName}
      practiceName={project.branding.practiceName}
      treeBasePath={`${basePath}/tree`}
      profilePathBase={`${basePath}/people`}
      storyPathBase={`${basePath}/stories`}
      focusStory={canvas.focusStory}
      lineages={canvas.availableLineages}
      selectedLineageId={canvas.selectedLineageId}
      depth={canvas.depth}
      maxDepth={canvas.maxDepth}
      queryString={serializeQuery(query)}
      shareToken={stringParam(query.share)}
    />
  );
}

function stringParam(value: string | string[] | undefined) {
  return typeof value === "string" ? value : undefined;
}

function serializeQuery(query: PageQuery) {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    if (Array.isArray(value)) value.forEach((item) => params.append(key, item));
    else if (value !== undefined) params.set(key, value);
  });
  return params.toString();
}
