"use client";

import { Fragment, useMemo, useRef, useState, useEffect } from "react";
import { useRouter } from "next/navigation";

import { FloatingControls } from "@/components/canvas-themed/floating-controls";
import { ThemedPersonNode } from "@/components/canvas-themed/themed-person-node";
import type { GenerationalLayout, GenerationalPersonSlot } from "@/lib/canvas/generational-layout";
import type { CanvasThemeManifest } from "@/lib/themes/types";
import type { Lineage, PersonViewModel } from "@/lib/types";

type ThemedTreeCanvasProps = {
  layout: GenerationalLayout;
  focusPerson: PersonViewModel;
  theme: CanvasThemeManifest;
  familyName: string;
  practiceName: string;
  treeBasePath: string;
  profilePathBase: string;
  storyPathBase: string;
  focusStory?: { id: string } | null;
  lineages: Lineage[];
  selectedLineageId?: string | null;
  depth: number;
  maxDepth: number;
  queryString?: string;
  shareToken?: string | null;
};

export function ThemedTreeCanvas({
  layout,
  focusPerson,
  theme,
  familyName,
  practiceName,
  treeBasePath,
  profilePathBase,
  storyPathBase,
  focusStory,
  lineages,
  selectedLineageId,
  depth,
  maxDepth,
  queryString = "",
  shareToken,
}: ThemedTreeCanvasProps) {
  const router = useRouter();
  const canvasRef = useRef<HTMLElement>(null);
  const searchDialogRef = useRef<HTMLDialogElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [search, setSearch] = useState("");
  const [isTransitioning, setIsTransitioning] = useState(false);
  const visiblePeople = useMemo(() => {
    const byId = new Map<string, GenerationalPersonSlot>();
    layout.rows.forEach((row) => {
      row.slots.forEach((slot) => {
        if (slot.kind === "person") byId.set(slot.id, slot);
      });
    });
    return [...byId.values()].sort((left, right) =>
      left.person.fullName.localeCompare(right.person.fullName),
    );
  }, [layout.rows]);
  const filteredPeople = visiblePeople.filter((slot) =>
    slot.person.fullName.toLowerCase().includes(search.trim().toLowerCase()),
  );

  useEffect(() => {
    const focusNode = canvasRef.current?.querySelector<HTMLElement>("[data-focus-person='true']");
    if (!focusNode) return;
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    focusNode.scrollIntoView({
      behavior: reducedMotion ? "auto" : "smooth",
      block: "center",
      inline: "center",
    });
    const frame = window.requestAnimationFrame(() => setIsTransitioning(false));
    return () => window.cancelAnimationFrame(frame);
  }, [layout.focusPersonId]);

  const pushParams = (mutate: (params: URLSearchParams) => void) => {
    const params = new URLSearchParams(queryString);
    mutate(params);
    if (shareToken) params.set("share", shareToken);
    const query = params.toString();
    router.push(query ? `${treeBasePath}?${query}` : treeBasePath, { scroll: false });
  };

  const selectPerson = (personId: string) => {
    if (personId === layout.focusPersonId) return;
    searchDialogRef.current?.close();
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reducedMotion) {
      pushParams((params) => params.set("person", personId));
      return;
    }
    setIsTransitioning(true);
    window.setTimeout(() => {
      pushParams((params) => params.set("person", personId));
    }, 120);
  };

  const openSearch = () => {
    setSearch("");
    searchDialogRef.current?.showModal();
    window.setTimeout(() => searchInputRef.current?.focus(), 0);
  };

  return (
    <section
      ref={canvasRef}
      className={`themed-tree-canvas${isTransitioning ? " is-transitioning" : ""}`}
      data-canvas-theme={theme.cssScope}
    >
      <div className="themed-canvas-frame" aria-hidden="true" />
      <header className="themed-tree-title-band">
        <p className="themed-tree-practice">Presented by {practiceName}</p>
        <h1>{familyName}</h1>
        <p className="themed-tree-relationship">{relationshipCaption(focusPerson)}</p>
      </header>

      <div className="themed-generation-stack">
        {layout.rows.map((row, rowIndex) => (
          <Fragment key={row.id}>
            <section
              className={`themed-generation-row${row.generation === 0 ? " themed-generation-row--focus" : ""}`}
              aria-labelledby={`${row.id}-label`}
            >
              <h2 id={`${row.id}-label`}>{theme.voice.generationLabels[row.labelKey] ?? row.labelKey}</h2>
              <div className="themed-generation-rail">
                {row.slots.map((slot, slotIndex) => {
                  const nextSlot = row.slots[slotIndex + 1];
                  const union = nextSlot
                    ? row.unions.find(
                        (candidate) =>
                          candidate.memberIds.includes(slot.id) &&
                          candidate.memberIds.includes(nextSlot.id),
                      )
                    : null;
                  return (
                    <Fragment key={slot.id}>
                      <ThemedPersonNode
                        slot={slot}
                        theme={theme}
                        onSelect={selectPerson}
                        profileHref={
                          slot.kind === "person" && slot.isFocus
                            ? withShare(`${profilePathBase}/${slot.id}`, shareToken)
                            : undefined
                        }
                        storyHref={
                          slot.kind === "person" && slot.isFocus && focusStory
                            ? withShare(`${storyPathBase}/${focusStory.id}`, shareToken)
                            : null
                        }
                      />
                      {union ? (
                        <span className="themed-couple-union" aria-label="Couple">
                          <span />
                        </span>
                      ) : null}
                    </Fragment>
                  );
                })}
              </div>
            </section>
            {rowIndex < layout.rows.length - 1 ? (
              <div className="themed-generation-join" aria-hidden="true">
                <span />
              </div>
            ) : null}
          </Fragment>
        ))}
      </div>

      <p className="themed-scroll-cue">
        <span aria-hidden="true">â—†</span> {theme.voice.scrollCue} <span aria-hidden="true">â—†</span>
      </p>

      <FloatingControls
        depth={depth}
        maxDepth={maxDepth}
        lineages={lineages}
        selectedLineageId={selectedLineageId}
        fullscreenTarget={canvasRef}
        onSearch={openSearch}
        onDepthChange={(nextDepth) =>
          pushParams((params) => {
            if (nextDepth === 1) params.delete("depth");
            else params.set("depth", String(nextDepth));
          })
        }
        onLineageChange={(lineageId) =>
          pushParams((params) => {
            if (lineageId) params.set("lineage", lineageId);
            else params.delete("lineage");
          })
        }
      />

      <dialog
        ref={searchDialogRef}
        className="themed-search-dialog"
        aria-labelledby="themed-search-title"
        onClose={() => setSearch("")}
      >
        <div className="themed-search-header">
          <div>
            <p>Archive index</p>
            <h2 id="themed-search-title">Find a family member</h2>
          </div>
          <button
            type="button"
            onClick={() => searchDialogRef.current?.close()}
            aria-label="Close search"
          >
            Ã—
          </button>
        </div>
        <input
          ref={searchInputRef}
          type="search"
          value={search}
          onChange={(event) => setSearch(event.target.value)}
          placeholder="Type a name"
          aria-label="Filter visible people by name"
        />
        <ul className="themed-search-results">
          {filteredPeople.map((slot) => (
            <li key={slot.id}>
              <button type="button" onClick={() => selectPerson(slot.id)}>
                <span>{slot.person.fullName}</span>
                <small>{slot.person.isLiving ? "Living" : roleForSearch(slot.role)}</small>
              </button>
            </li>
          ))}
        </ul>
        {filteredPeople.length === 0 ? <p className="themed-search-empty">No matching archive entry.</p> : null}
      </dialog>
    </section>
  );
}

function relationshipCaption(person: PersonViewModel) {
  const parts: string[] = [];
  const firstName = person.givenName || person.fullName.split(" ")[0];
  const parentNames = person.relatives.parents.map(firstNameOf);
  const spouseNames = person.relatives.spouses.map(firstNameOf);
  const childNames = person.relatives.children.map(firstNameOf);

  if (parentNames.length) parts.push(`${childWord(person.gender)} of ${joinNames(parentNames)}`);
  if (spouseNames.length) parts.push(`${spouseWord(person.gender)} of ${joinNames(spouseNames)}`);
  if (childNames.length) parts.push(`${parentWord(person.gender)} of ${joinNames(childNames)}`);
  return parts.length ? `${firstName}, ${parts.join(" Â· ")}` : `${firstName}, family record in focus`;
}

function firstNameOf(person: { givenName: string; fullName: string }) {
  return person.givenName || person.fullName.split(" ")[0];
}

function joinNames(names: string[]) {
  if (names.length <= 2) return names.join(" & ");
  return `${names.slice(0, -1).join(", ")} & ${names.at(-1)}`;
}

function childWord(gender: PersonViewModel["gender"]) {
  return gender === "female" ? "daughter" : gender === "male" ? "son" : "child";
}

function spouseWord(gender: PersonViewModel["gender"]) {
  return gender === "female" ? "wife" : gender === "male" ? "husband" : "spouse";
}

function parentWord(gender: PersonViewModel["gender"]) {
  return gender === "female" ? "mother" : gender === "male" ? "father" : "parent";
}

function roleForSearch(role: GenerationalPersonSlot["role"]) {
  return role === "focus" ? "Current focus" : role[0].toUpperCase() + role.slice(1);
}

function withShare(path: string, shareToken?: string | null) {
  return shareToken ? `${path}?share=${encodeURIComponent(shareToken)}` : path;
}
"use client";

import { useEffect, useState } from "react";

import type { Lineage } from "@/lib/types";

type FloatingControlsProps = {
  depth: number;
  maxDepth: number;
  lineages: Lineage[];
  selectedLineageId?: string | null;
  fullscreenTarget: React.RefObject<HTMLElement | null>;
  onSearch: () => void;
  onDepthChange: (depth: number) => void;
  onLineageChange: (lineageId: string | null) => void;
};

export function FloatingControls({
  depth,
  maxDepth,
  lineages,
  selectedLineageId,
  fullscreenTarget,
  onSearch,
  onDepthChange,
  onLineageChange,
}: FloatingControlsProps) {
  const [fullscreenSupported, setFullscreenSupported] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  useEffect(() => {
    const supportCheck = window.setTimeout(
      () => setFullscreenSupported("requestFullscreen" in document.documentElement),
      0,
    );
    const syncFullscreen = () => setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", syncFullscreen);
    return () => {
      window.clearTimeout(supportCheck);
      document.removeEventListener("fullscreenchange", syncFullscreen);
    };
  }, []);

  const toggleFullscreen = async () => {
    if (document.fullscreenElement) {
      await document.exitFullscreen();
    } else {
      await fullscreenTarget.current?.requestFullscreen();
    }
  };

  return (
    <nav className="themed-floating-controls" aria-label="Tree canvas controls">
      <button type="button" onClick={onSearch} aria-label="Search visible people">
        <span aria-hidden="true">âŒ•</span>
        <span className="themed-control-label">Search</span>
      </button>

      <div className="themed-depth-stepper" aria-label="Visible generation depth">
        <button
          type="button"
          disabled={depth <= 1}
          onClick={() => onDepthChange(Math.max(1, depth - 1))}
          aria-label="Show one fewer generation"
        >
          âˆ’
        </button>
        <output aria-live="polite" aria-label={`${depth} generation steps`}>
          <span className="themed-control-label">Depth </span>
          {depth}
        </output>
        <button
          type="button"
          disabled={depth >= maxDepth}
          onClick={() => onDepthChange(Math.min(maxDepth, depth + 1))}
          aria-label="Show one more generation"
        >
          +
        </button>
      </div>

      <label className="themed-lineage-control">
        <span className="themed-control-label">Branch</span>
        <select
          aria-label="Filter by family branch"
          value={selectedLineageId ?? ""}
          onChange={(event) => onLineageChange(event.target.value || null)}
        >
          <option value="">All branches</option>
          {lineages.map((lineage) => (
            <option key={lineage.id} value={lineage.id}>
              {lineage.name}
            </option>
          ))}
        </select>
      </label>

      {fullscreenSupported ? (
        <button
          type="button"
          onClick={toggleFullscreen}
          aria-label={isFullscreen ? "Exit fullscreen" : "Enter fullscreen"}
        >
          <span aria-hidden="true">{isFullscreen ? "âŠ¡" : "â–¡"}</span>
          <span className="themed-control-label">Fullscreen</span>
        </button>
      ) : null}
    </nav>
  );
}

